def test_bruteforce_windows(run, x):
    p = list(map(int, x.split()[1:]))
    total = 0
    for l in range(len(p)):
        for r in range(l + 1, len(p)):
            total += sorted(p[l:r + 1])[-2]
    out = run(x)
    assert out.strip() == str(total)

def test_top_two_scan(run, x):
    p = list(map(int, x.split()[1:]))
    total = 0
    for l in range(len(p) - 1):
        first = second = -1
        for r in range(l, len(p)):
            v = p[r]
            if v > first:
                second, first = first, v
            elif v > second:
                second = v
            if r > l:
                total += second
    out = run(x)
    assert out.strip() == str(total)

def test_sorted_suffixes(run, x):
    p = list(map(int, x.split()[1:]))
    expected = sum(sorted(p[l:r + 1])[-2]
                   for l in range(len(p))
                   for r in range(l + 1, len(p)))
    out = run(x)
    assert out.strip() == str(expected)

def test_pair_extension(run, x):
    p = list(map(int, x.split()[1:]))
    expected = 0
    for left in range(len(p)):
        for right in range(left + 1, len(p)):
            values = p[left:right + 1]
            values.sort()
            expected += values[len(values) - 2]
    out = run(x)
    assert out.strip() == str(expected)

