def test_delete_bruteforce(run, x):
    a = list(map(int, x.split()[1:]))
    best = min(max(b[i + 1] - b[i] for i in range(len(b) - 1)) for b in (a[:k] + a[k + 1:] for k in range(1, len(a) - 1)))
    assert run(x).strip() == str(best)

def test_gap_merge(run, x):
    a = list(map(int, x.split()[1:]))
    gaps = [a[i + 1] - a[i] for i in range(len(a) - 1)]
    vals = []
    for k in range(1, len(a) - 1):
        g = gaps[:k - 1] + [a[k + 1] - a[k - 1]] + gaps[k + 1:]
        vals.append(max(g))
    assert run(x).strip() == str(min(vals))

def test_pair_scan(run, x):
    a = list(map(int, x.split()[1:]))
    answer = 10**9
    for skip in range(1, len(a) - 1):
        worst = 0
        previous = None
        for i, value in enumerate(a):
            if i != skip:
                if previous is not None:
                    worst = max(worst, value - previous)
                previous = value
        answer = min(answer, worst)
    assert run(x).strip() == str(answer)

def test_candidate_tracks(run, x):
    a = list(map(int, x.split()[1:]))
    candidates = []
    for removed in range(1, len(a) - 1):
        track = [a[i] for i in range(len(a)) if i != removed]
        candidates.append(max(y - z for z, y in zip(track, track[1:])))
    assert run(x).strip() == str(min(candidates))

def test_local_join(run, x):
    a = list(map(int, x.split()[1:]))
    result = 10**9
    for j in range(1, len(a) - 1):
        maximum = 0
        for i in range(len(a) - 1):
            if i == j - 1:
                maximum = max(maximum, a[j + 1] - a[j - 1])
            elif i != j:
                maximum = max(maximum, a[i + 1] - a[i])
        result = min(result, maximum)
    assert run(x).strip() == str(result)

def test_max_after_skip(run, x):
    a = list(map(int, x.split()[1:]))
    scores = []
    for s in range(1, len(a) - 1):
        kept = a[:s] + a[s + 1:]
        scores.append(max(kept[q] - kept[q - 1] for q in range(1, len(kept))))
    expected = min(scores)
    assert run(x).strip() == str(expected)

def test_retained_neighbors(run, x):
    a = list(map(int, x.split()[1:]))
    expected = 10**9
    for omit in range(1, len(a) - 1):
        retained = []
        for index in range(len(a)):
            if index != omit:
                retained.append(a[index])
        difficulty = max(retained[index] - retained[index - 1] for index in range(1, len(retained)))
        if difficulty < expected:
            expected = difficulty
    assert run(x).strip() == str(expected)

def test_all_removals(run, x):
    a = list(map(int, x.split()[1:]))
    answer = None
    for r in range(1, len(a) - 1):
        last = a[0]
        worst = 0
        for i in range(1, len(a)):
            if i != r:
                worst = max(worst, a[i] - last)
                last = a[i]
        answer = worst if answer is None else min(answer, worst)
    assert run(x).strip() == str(answer)

def test_minimax(run, x):
    a = list(map(int, x.split()[1:]))
    expected = min(
        max(a[v] - a[u] for u, v in zip([i for i in range(len(a)) if i != r], [i for i in range(len(a)) if i != r][1:]))
        for r in range(1, len(a) - 1)
    )
    assert run(x).strip() == str(expected)

def test_definition_oracle(run, x):
    a = list(map(int, x.split()[1:]))
    difficulties = []
    for removed in range(1, len(a) - 1):
        d = -1
        left = 0
        for right in range(1, len(a)):
            if right == removed:
                continue
            d = max(d, a[right] - a[left])
            left = right
        difficulties.append(d)
    assert run(x).strip() == str(min(difficulties))

def test_bruteforce_pairs(run, x):
    l, r = map(int, x.split())
    out = run(x).strip()
    assert out.isdecimal()
    got = int(out)
    assert 0 <= got < 1000000007
    if r - l <= 64:
        want = 0
        for a in range(l, r + 1):
            for b in range(a, r + 1):
                if b % a == (b ^ a):
                    want += 1
        assert got == want % 1000000007


