def test_directional_bruteforce(run, x):
    a = [list(map(int, line.split())) for line in x.strip().splitlines()[1:]]
    n, m = len(a), len(a[0])
    want = 0
    for i in range(n):
        for j in range(m):
            if a[i][j] == 0:
                for di, dj in ((0, 1), (0, -1), (1, 0), (-1, 0)):
                    y, z = i + di, j + dj
                    while 0 <= y < n and 0 <= z < m:
                        if a[y][z]:
                            want += 1
                            break
                        y, z = y + di, z + dj
    assert run(x).strip() == str(want)

def test_scan_until_actor(run, x):
    g = [list(map(int, q.split())) for q in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        for j in range(m):
            if not g[i][j]:
                want += any(g[i][k] for k in range(j))
                want += any(g[i][k] for k in range(j + 1, m))
                want += any(g[k][j] for k in range(i))
                want += any(g[k][j] for k in range(i + 1, n))
    assert run(x).strip() == str(want)

def test_row_column_rays(run, x):
    rows = x.strip().splitlines()
    g = [list(map(int, q.split())) for q in rows[1:]]
    n, m = len(g), len(g[0])
    want = sum(1 for i in range(n) for j in range(m) for ray in (g[i][:j], g[i][j+1:], [g[k][j] for k in range(i)], [g[k][j] for k in range(i+1, n)]) if g[i][j] == 0 and 1 in ray)
    assert run(x).strip() == str(want)

def test_prefix_visibility(run, x):
    g = [list(map(int, q.split())) for q in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i in range(n):
        left = right = False
        for j in range(m):
            if g[i][j] == 0 and left: want += 1
            left = left or bool(g[i][j])
        for j in range(m - 1, -1, -1):
            if g[i][j] == 0 and right: want += 1
            right = right or bool(g[i][j])
    for j in range(m):
        up = down = False
        for i in range(n):
            if g[i][j] == 0 and up: want += 1
            up = up or bool(g[i][j])
        for i in range(n - 1, -1, -1):
            if g[i][j] == 0 and down: want += 1
            down = down or bool(g[i][j])
    assert run(x).strip() == str(want)

def test_cellwise_sum(run, x):
    g = [list(map(int, q.split())) for q in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    want = 0
    for i, row in enumerate(g):
        for j, value in enumerate(row):
            if value == 0:
                want += sum((any(g[i][k] for k in range(j)), any(g[i][k] for k in range(j + 1, m)), any(g[k][j] for k in range(i)), any(g[k][j] for k in range(i + 1, n))))
    assert run(x).strip() == str(want)

