def test_small_exhaustive(run, x):
    g = [list(map(int, q.split())) for q in x.strip().splitlines()[1:]]
    n, m = len(g), len(g[0])
    rays = ((lambda i,j: ((i,k) for k in range(j))), (lambda i,j: ((i,k) for k in range(j+1,m))), (lambda i,j: ((k,j) for k in range(i))), (lambda i,j: ((k,j) for k in range(i+1,n))))
    want = sum(any(g[y][z] for y,z in ray(i,j)) for i in range(n) for j in range(m) if g[i][j] == 0 for ray in rays)
    assert run(x).strip() == str(want)

def test_direct_small(run, x):
    L, R = map(int, x.split())
    a = int(run(x).strip())
    assert 0 <= a < 1000000007
    if R - L <= 8:
        z = sum(y % q == (y ^ q) for q in range(L, R + 1) for y in range(q, R + 1))
        assert a == z % 1000000007


