def test_two_ascending(run, x):
    out = run(x).split()
    if x.splitlines()[0] == '2' and x.splitlines()[1] == '1 2':
        assert out == ['2', '1']
    else:
        assert True

def test_two_descending(run, x):
    out = run(x).split()
    if x.splitlines()[0] == '2' and x.splitlines()[1] == '1000 1':
        assert out == ['1000', '1']
    else:
        assert True

def test_three_ascending(run, x):
    out = run(x).split()
    if x.splitlines()[0] == '3' and x.splitlines()[1] == '1 2 3':
        assert out == ['4', '2']
    else:
        assert True

def test_three_mixed(run, x):
    out = run(x).split()
    if x.splitlines()[0] == '3' and x.splitlines()[1] == '1000 1 2':
        assert out == ['1001', '2']
    else:
        assert True

def test_singleton(run, x):
    out = run(x).split()
    if x.splitlines()[0] == '1':
        assert out == ['1000', '0']
    else:
        assert True

def test_four_ascending(run, x):
    out = run(x).split()
    if x.splitlines()[0] == '4' and x.splitlines()[1] == '1 2 3 4':
        assert out == ['6', '4']
    else:
        assert True

def test_four_descending(run, x):
    out = run(x).split()
    if x.splitlines()[0] == '4' and x.splitlines()[1] == '4 3 2 1':
        assert out == ['6', '4']
    else:
        assert True

def test_four_mixed(run, x):
    out = run(x).split()
    if x.splitlines()[0] == '4' and x.splitlines()[1] == '3 1 2 4':
        assert out == ['6', '4']
    else:
        assert True

def test_five_alternating(run, x):
    out = run(x).split()
    if x.splitlines()[0] == '5':
        assert out == ['2000', '1000']
    else:
        assert True

def test_thousand_ascending(run, x):
    out = run(x).split()
    if x.splitlines()[0] == '1000':
        assert out == ['250500', '250000']
    else:
        assert True

