def test_single_one(run, x):
    a = list(map(int, x.splitlines()[1].split()))
    r = bytearray(sum(a) + 1); r[0] = 1
    expected = -1
    for s in range(1, len(r)):
        r[s] = any(c <= s and r[s-c] for c in a)
        if not r[s]:
            expected = s; break
    assert run(x).strip() == str(expected)

