def test_trace_first_gap(run, x):
    a = x.split(); p = int(a[1]); s = 0
    for w in a[2:][::-1]: s = 2*s + (w == 'halfplus')
    money = 0
    for w in a[2:]:
        if w == 'half': money += (s//2)*p
        else: money += (s//2)*p + p//2
        s //= 2
    assert run(x).strip() == str(money)

def test_trace_second_gap(run, x):
    z=x.split(); p=int(z[1]); stock=0
    for kind in reversed(z[2:]): stock=stock*2+(kind=='halfplus')
    total=0
    for kind in z[2:]:
        total += (stock//2)*p + (p//2 if kind=='halfplus' else 0)
        stock//=2
    assert run(x).strip()==str(total)

def test_trace_middle_gap(run, x):
    v=x.split(); p=int(v[1]); apples=0
    for k in v[:1:-1]:
        apples=2*apples+(1 if k=='halfplus' else 0)
    paid=0
    for k in v[2:]:
        paid += apples*p//2
        apples//=2
    assert run(x).strip()==str(paid)

def test_trace_last_gap(run, x):
    q=x.split(); price=int(q[1]); left=0
    for buyer in reversed(q[2:]): left=2*left+(buyer=='halfplus')
    result=0
    for buyer in q[2:]:
        result += left//2*price + (price//2 if buyer=='halfplus' else 0)
        left//=2
    assert run(x).strip()==str(result)

def test_trace_two_halves(run, x):
    f=x.split(); p=int(f[1]); inventory=0
    for event in reversed(f[2:]): inventory=(inventory<<1)+(event=='halfplus')
    earned=0
    for event in f[2:]:
        earned += inventory*p//2
        inventory//=2
    assert run(x).strip()==str(earned)

