def test_perm_flat_min(run, x):
    from itertools import permutations
    a = list(map(int, x.split())); n = a[0]
    if n > 8:
        run(x); return
    op = a[1:n+1]; par = a[n+1:]
    ch = [[] for _ in range(n)]
    for i, p in enumerate(par, 1): ch[p-1].append(i)
    leaf = [i for i in range(n) if not ch[i]]; k = len(leaf); best = 0
    for q in permutations(range(1, k+1)):
        z = dict(zip(leaf, q))
        def f(u):
            if not ch[u]: return z[u]
            v = [f(w) for w in ch[u]]
            return max(v) if op[u] else min(v)
        best = max(best, f(0))
    s = run(x).strip(); assert s.lstrip('-').isdigit(); assert int(s) == best

