    d = list(map(int, x.split())); n = d[0]
    if n > 8:
        run(x); return
    op = d[1:n+1]; ch = [[] for _ in range(n)]
    for i, p in enumerate(d[n+1:], 1): ch[p-1].append(i)
    lf = [i for i in range(n) if not ch[i]]; k = len(lf); ans = 1
    for t in range(1, k+1):
