def test_small_turns(run, x):
    a, b = map(int, x.split())
    need = 1
    while True:
        if need % 2:
            if a < need:
                expected = 'Vladik'
                break
            a -= need
        else:
            if b < need:
                expected = 'Valera'
                break
            b -= need
        need += 1
    assert run(x).strip() == expected

def test_early_valera(run, x):
    a, b = map(int, x.split())
    gift = 1
    while True:
        stock = a if gift % 2 else b
        if stock < gift:
            expected = 'Vladik' if gift % 2 else 'Valera'
            break
        if gift % 2:
            a -= gift
        else:
            b -= gift
        gift += 1
    assert run(x).strip() == expected

def test_odd_payment(run, x):
    a, b = map(int, x.split())
    amount = 1
    while a >= amount:
        a -= amount
        amount += 1
        if b < amount:
            expected = 'Valera'
            break
        b -= amount
        amount += 1
    else:
        expected = 'Vladik'
    assert run(x).strip() == expected

def test_even_payment(run, x):
    a, b = map(int, x.split())
    turn = 0
    while True:
        amount = turn + 1
        if turn % 2 == 0:
            if a < amount:
                expected = 'Vladik'
                break
            a -= amount
        else:
            if b < amount:
                expected = 'Valera'
                break
            b -= amount
        turn += 1
    assert run(x).strip() == expected

