    stocks = list(map(int, x.split()))
    amount = 1
    player = 0
    while stocks[player] >= amount:
        stocks[player] -= amount
        amount += 1
        player = 1 - player
    expected = ('Vladik', 'Valera')[player]
    assert run(x).strip() == expected

