def test_exhaustive_sets_a(run, x):
    from itertools import combinations
    z = list(map(int, x.split()))
    n, m = z[:2]; a = [z[2+i*m:2+(i+1)*m] for i in range(n)]
    good = set()
    for line in a + [[a[i][j] for i in range(n)] for j in range(m)]:
        for v in (0, 1):
            p = [(id(line), k) for k, q in enumerate(line) if q == v]
            for r in range(1, len(p)+1):
                good.update(combinations(p, r))
    # Rebuild with real coordinates, so equal singleton cells coincide.
    good = set()
    for i in range(n):
        for v in (0,1):
            p=[(i,j) for j in range(m) if a[i][j]==v]
            for r in range(1,len(p)+1): good.update(combinations(p,r))
    for j in range(m):
        for v in (0,1):
            p=[(i,j) for i in range(n) if a[i][j]==v]
            for r in range(1,len(p)+1): good.update(combinations(p,r))
    assert int(run(x).strip()) == len(good)

def test_exhaustive_sets_b(run, x):
    from itertools import combinations
    q=list(map(int,x.split())); n,m=q[:2]; a=[q[2+i*m:2+(i+1)*m] for i in range(n)]; s=set()
    for i in range(n):
        for v in (0,1):
            p=[(i,j) for j in range(m) if a[i][j]==v]
            for k in range(1,len(p)+1): s.update(combinations(p,k))
    for j in range(m):
        for v in (0,1):
            p=[(i,j) for i in range(n) if a[i][j]==v]
            for k in range(1,len(p)+1): s.update(combinations(p,k))
    assert int(run(x).strip())==len(s)

