        for fixed in range((n,m)[axis]):
            for v in (0,1):
                p=[(fixed,k) if axis==0 else (k,fixed) for k in range((m,n)[axis]) if a[fixed][k]==v if axis==0] if axis==0 else [(k,fixed) for k in range(n) if a[k][fixed]==v]
                for r in range(1,len(p)+1): s.update(combinations(p,r))
    assert int(run(x).strip())==len(s)

def test_exhaustive_sets_d(run, x):
