    for i in range(n):
        for c in range(2):
            p=[(i,j) for j in range(m) if a[i][j]==c]
            for k in range(1,len(p)+1): S|=set(combinations(p,k))
    for j in range(m):
        for c in range(2):
            p=[(i,j) for i in range(n) if a[i][j]==c]
            for k in range(1,len(p)+1): S|=set(combinations(p,k))
