def test_exhaustive_half_enumeration(run, x):
    n = int(x.strip())
    pals = []
    width = 1
    while len(pals) < n:
        for half in range(10 ** (width - 1), 10 ** width):
            s = str(half)
            pals.append(int(s + s[::-1]))
        width += 1
    assert int(run(x).strip()) == pals[n - 1]

def test_digit_product_oracle(run, x):
    from itertools import product
    n = int(x.strip())
    pals = []
    width = 1
    while len(pals) < n:
        for first in '123456789':
            for tail in product('0123456789', repeat=width - 1):
                half = first + ''.join(tail)
                pals.append(int(half + half[::-1]))
        width += 1
    assert int(run(x).strip()) == pals[n - 1]

def test_ranked_candidates(run, x):
    n = int(x.strip())
    candidates = []
    for digits in range(1, 5):
        lo = 1 if digits == 1 else 10 ** (digits - 1)
        for prefix in range(lo, 10 ** digits):
            text = str(prefix)
            candidates.append(int(text + text[::-1]))
    assert int(run(x).strip()) == candidates[n - 1]

